	@Test
	public void preparedDistributedGroupRetainsItsCapturedResultColumn() {
		IRI left = VF.createIRI("urn:delegation:left");
		IRI right = VF.createIRI("urn:delegation:right");
		try (RepositoryConnection first = getRepository(1).getConnection();
				RepositoryConnection second = getRepository(2).getConnection()) {
			first.add(SUBJECT, EDGE, OBJECT);
			first.add(SUBJECT, left, VF.createLiteral("left"));
			second.add(SUBJECT, right, VF.createLiteral("right"));
		}
		String text = "SELECT ?s ?value WHERE { ?s <urn:delegation:edge> ?value . "
				+ "?s <urn:delegation:left> ?left . ?s <urn:delegation:right> ?right }";
		try (RepositoryConnection connection = fedxRule.getRepository().getConnection()) {
			var query = connection.prepareTupleQuery(text);
			query.setBinding("value", OBJECT);
			try (var rows = query.evaluate()) {
				assertThat(QueryResults.asList(rows)).as("prepared distributed exclusive group")
						.extracting(row -> tuple(row.getValue("s"), row.getValue("value")))
						.containsExactly(tuple(SUBJECT, OBJECT));
			}
		}
	}

	private void addModeStatement() {
		try (RepositoryConnection connection = getRepository(1).getConnection()) {
			connection.add(SUBJECT, EDGE, OBJECT);
		}
	}

	private Dataset modeDataset(boolean singleMember) {
		if (!singleMember) {
			return null;
		}
		FedXDataset dataset = new FedXDataset(null);
		dataset.addEndpoint(federationContext().getEndpointManager().getEndpointByName("http://endpoint1").getId());
		return dataset;
	}

	private static void assertModeResults(FederationEvaluationStrategy strategy, TupleExpr plan, String scenario,
			Value... subjects) {
		try (var rows = strategy.evaluate(plan, EmptyBindingSet.getInstance())) {
			assertThat(QueryResults.asList(rows)).as(scenario)
					.extracting(row -> row.getValue("s"))
					.containsExactlyInAnyOrder(subjects);
		}
	}

	@Test
	public void declaredEmptyNestedGraphDoesNotAcquireStatementOrigin() {
		IRI emptyGraph = VF.createIRI("urn:delegation:declaredEmpty");
		SimpleDataset dataset = new SimpleDataset();
		dataset.addNamedGraph(GRAPH);
		dataset.addNamedGraph(emptyGraph);
		String text = "SELECT ?g ?claim ?source WHERE { GRAPH ?g { ?claim <" + SOURCE
				+ "> ?source . GRAPH <" + emptyGraph + "> {} } }";
		assertThat(optimize(text, dataset)).isNotInstanceOf(SingleSourceQuery.class);
		assertThat(query(text, dataset))
				.extracting(row -> tuple(row.getValue("g"), identity(row.getValue("claim")), row.getValue("source")))
				.containsExactly(tuple(GRAPH,
						memberValue(federationContext().getEndpointManager().getEndpointByName("http://endpoint1"),
								CLAIM),
						VF.createLiteral("local source")));
	}

	private TupleExpr optimize(String text, Dataset dataset) {
		var parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, text, null);
		var context = federationContext();
		var strategy = context.createStrategy(dataset);
		var queryInfo = new QueryInfo(text, null, QueryType.SELECT, 0, false, context, strategy, dataset);
		return strategy.optimize(parsed.getTupleExpr(), new FederationEvaluationStatistics(queryInfo, dataset),
				EmptyBindingSet.getInstance());
	}

	private List<BindingSet> query(String text, Dataset dataset) {
		try (RepositoryConnection connection = fedxRule.getRepository().getConnection()) {
			var prepared = connection.prepareTupleQuery(text);
			prepared.setDataset(dataset);
			try (var rows = prepared.evaluate()) {
				assertThat(rows.getBindingNames()).containsExactlyInAnyOrderElementsOf(
						QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, text, null)
								.getTupleExpr()
								.getBindingNames());
				return QueryResults.asList(rows);
			}
		}
	}

	private void assertTermRows(List<BindingSet> rows) {
		rows.forEach(row -> assertThat(row.getBindingNames()).containsExactlyInAnyOrder("g", "part", "tail", "source"));
		assertThat(rows).extracting(
				row -> tuple(row.getValue("g"), row.getValue("part"), row.getValue("tail"), row.getValue("source")))
				.containsExactly(tuple(GRAPH, SUBJECT, OBJECT, VF.createLiteral("local source")));
	}
